   ground+=liquid*.35;const base=ground*.25;ground-=base;const runoff=liquid*.65+base;
   if(cycle===5){if(northern){northernSnow[m].snowfall_m3+=(t<0?p:0)*a;northernSnow[m].melt_m3+=melt*a;}const b=budgets[m];b.precipitation_m3+=p*a;b.evaporation_m3+=evap*a;b.runoff_m3+=runoff*a;b.storage_change_m3+=(snow+ground-start)*a;discharge[m][i]=runoff*a/seconds;}
  }
  }
  if(k%12000===0)await new Promise(r=>setTimeout(r,0));
 }
